"""Generate standalone guide from the palette and typography used by the app."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
palette=json.loads((ROOT/'ui/palette.json').read_text())
colors='\n'.join('[data-theme='+theme+']{'+''.join('--color-'+k+':'+v+';' for k,v in values.items() if k!='map-style')+'}' for theme,values in palette.items())
css=(ROOT/'ui/tokens.css').read_text().replace('/app/static/','static/')
sections=[]
for theme in palette:
    rows=''.join(f'<tr><td>{name}</td><td>{value}</td></tr>' for name,value in palette[theme].items())
    sections.append(f'''<article class="sheet" data-theme="{theme}"><img src="static/brand/logo-{theme}.png" alt="C1V1C — Tulabhara AI"><h2>{theme.title()} workspace</h2><p>Compare the cost of a greener city with the needs of the people who live in it.</p><span class="tag">Demonstration data · grade D</span><section><h3>Navigation and actions</h3><nav class="row"><button class="primary" aria-current="page">Home</button><button>City Intelligence</button></nav><div class="row"><button class="primary">Preview allocation</button><button>Inspect sources</button><button disabled>Loading preview…</button></div></section><section><h3>Inputs and feedback</h3><label>Capital budget · INR crore <input type="number" value="2" min="0"></label><label>Invalid budget <input class="error" aria-invalid="true" value="-1"></label><p class="error">Enter a budget of zero or more.</p><label>Unavailable source <input disabled value="Awaiting validated geometry"></label><p class="notice">Synthetic fixtures, not observed Bengaluru conditions.</p></section><section><h3>Before a plan exists</h3><p>Choose the budget and interventions. Preview the cost ledger, then inspect trade-offs and evidence.</p><details><summary>What is a heat exposure index?</summary><p>A relative indicator, not a predicted temperature change.</p></details></section><section><h3>Colors</h3><div class="data-ledger"><table><thead><tr><th>Token</th><th>Value</th></tr></thead><tbody>{rows}</tbody></table></div></section><section><h3>Guest workspace</h3><p>No account is connected. Preferences stay in this browser; preview history lasts for this session.</p></section><section><h3>Shared geometry & type tokens</h3><pre class="token-list"></pre></section></article>''')
script="""document.querySelectorAll('.token-list').forEach(el=>{const r=[...document.styleSheets[0].cssRules].find(r=>r.selectorText===':root');el.textContent=[...r.style].map(k=>k+': '+r.style.getPropertyValue(k)).join('\\n')})"""
(ROOT/'style-guide.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>C1V1C brand system</title><style>'+css+colors+'pre{white-space:pre-wrap;overflow-wrap:anywhere}</style><body data-theme="light"><main class="guide"><h1>C1V1C / Brand system</h1><p>Official identity. One planning workspace. Two considered themes.</p><div class="pair">'+''.join(sections)+'</div></main><script>'+script+'</script></body></html>',encoding='utf-8')
